#include <list>
#include <iostream>

int main() {
    std::list<int> l1 = {1, 2, 3};
    std::list<int> l2 = {4, 5, 6};

    // O(1) transfer of all elements from l2 to l1 before l1.end()
    l1.splice(l1.end(), l2);

    std::cout << "l1 size: " << l1.size() << " (Expected 6)\n"; 
    std::cout << "l2 size: " << l2.size() << " (Expected 0)\n"; 

    // Self-splice (moving element 3 to the front)
    auto it_three = l1.begin();
    std::advance(it_three, 2); // Points to 3
    l1.splice(l1.begin(), l1, it_three);
}
